// Embed API.md into a TypeScript module so the public /api-docs route can serve
// it with zero filesystem access at request time.
//
// WHY CODEGEN: `output: "standalone"` ships only the traced server bundle —
// a repo-root .md read with `fs` at runtime is not part of it, and the deploy
// assembles the standalone dir separately (see deploy.sh). Embedding the text
// at build time makes the route work identically in dev, prod, and standalone.
//
// Runs from the `predev` / `prebuild` npm hooks. The generated file is
// git-ignored — API.md is the single source of truth.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "API.md");
const target = join(root, "src", "features", "docs", "api-doc.generated.ts");

const markdown = readFileSync(source, "utf8");

// JSON.stringify — not a template literal: API.md is full of backticks and
// `${...}`-looking shell interpolation that would break or execute in one.
const file = `// GENERATED by scripts/gen-api-docs.mjs from API.md — do not edit.
// Regenerate with \`node scripts/gen-api-docs.mjs\` (runs on predev/prebuild).

export const API_DOC_MARKDOWN = ${JSON.stringify(markdown)};
`;

mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, file, "utf8");
console.log(`[gen-api-docs] ${markdown.length} chars -> src/features/docs/api-doc.generated.ts`);
